module boat_transport (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] c50,\n    input wire [3:0] c100,\n    input wire [9:0] k,\n    output reg [7:0] min_rides,\n    output reg [31:0] ways,\n    output reg done\n);\n\n    // Parameters\n    parameter MAX_ITER = 100;\n    parameter INF = 8'hFF;\n    parameter MOD = 32'd1000000007;\n\n    // State definitions\n    localparam [2:0] IDLE      = 3'd0;\n    localparam [2:0] INIT      = 3'd1;\n    localparam [2:0] SET_DEPTH = 3'd2;\n    localparam [2:0] CHECK_STATE = 3'd3;\n    localparam [2:0] NEXT_STATE = 3'd4;\n    localparam [2:0] CHECK_MOVE = 3'd5;\n    localparam [2:0] DONE_ST    = 3'd6;\n\n    // Internal registers\n    reg [2:0] state;\n    reg [7:0] dist [0:8][0:8][0:1];  // distance array\n    reg [31:0] ways_arr [0:8][0:8][0:1];  // ways array\n    reg [7:0] C [0:8][0:8];  // combination table\n    reg [3:0] i, j, s; \n    reg [3:0] x, y;\n    reg [3:0] max_x, max_y;\n    reg [7:0] current_depth;\n\n    // Combinational combination table\n    integer idx1, idx2;\n    always @(*) begin\n        for (idx1 = 0; idx1 <= 8; idx1 = idx1 + 1) begin\n            for (idx2 = 0; idx2 <= 8; idx2 = idx2 + 1) begin\n                if (idx2 > idx1) C[idx1][idx2] = 8'd0;\n                else if (idx2 == 0 || idx2 == idx1) C[idx1][idx2] = 8'd1;\n                else if (idx1 == 4'd1) C[idx1][idx2] = 8'd1;\n                else if (idx1 == 4'd2) C[idx1][idx2] = (idx2 == 4'd1) ? 8'd2 : 8'd1;\n                else if (idx1 == 4'd3) C[idx1][idx2] = (idx2 == 1 || idx2 == 2) ? 8'd3 : 8'd1;\n                else if (idx1 == 4'd4) C[idx1][idx2] = (idx2 == 2) ? 8'd6 : (idx2 == 1 || idx2 == 3) ? 8'd4 : 8'd1;\n                else if (idx1 == 4'd5) C[idx1][idx2] = (idx2 == 2) ? 8'd10 : (idx2 == 3) ? 8'd10 : (idx2 == 1 || idx2 == 4) ? 8'd5 : 8'd1;\n                else if (idx1 == 4'd6) C[idx1][idx2] = (idx2 == 3) ? 8'd20 : (idx2 == 2 || idx2 == 4) ? 8'd15 : (idx2 == 1 || idx2 == 5) ? 8'd6 : 8'd1;\n                else if (idx1 == 4'd7) C[idx1][idx2] = (idx2 == 3) ? 8'd35 : (idx2 == 4) ? 8'd35 : (idx2 == 2 || idx2 == 5) ? 8'd21 : (idx2 == 1 || idx2 == 6) ? 8'd7 : 8'd1;\n                else if (idx1 == 4'd8) C[idx1][idx2] = (idx2 == 4) ? 8'd70 : (idx2 == 3 || idx2 == 5) ? 8'd56 : (idx2 == 2 || idx2 == 6) ? 8'd28 : (idx2 == 1 || idx2 == 7) ? 8'd8 : 8'd1;\n                else C[idx1][idx2] = 8'd0;\n            end\n        end\n    end\n\n    // Main FSM\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Initialize all registers\n            state <= IDLE;\n            done <= 1'b0;\n            min_rides <= 8'd0;\n            ways <= 32'd0;\n            current_depth <= 8'd0;\n            i <= 4'd0;\n            j <= 4'd0;\n            s <= 1'b0;\n            x <= 4'd0;\n            y <= 4'd0;\n            // Initialize arrays through loops\n            for (i = 0; i <= 8; i = i + 1) begin\n                for (j = 0; j <= 8; j = j + 1) begin\n                    for (s = 0; s < 1; s = s + 1) begin\n                        dist[i][j][s] <= INF;\n                        ways_arr[i][j][s] <= 32'd0;\n                    end\n                end\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) state <= INIT;\n                end\n\n                INIT: begin\n                    // Reset array values\n                    for (i = 0; i <= 8; i = i + 1) begin\n                        for (j = 0; j <= 8; j = j + 1) begin\n                            for (s = 0; s <= 1; s = s + 1) begin\n                                dist[i][j][s] <= INF;\n                                ways_arr[i][j][s] <= 32'd0;\n                            end\n                        end\n                    end\n                    dist[c50][c100][1'b0] <= 8'd0;\n                    ways_arr[c50][c100][1'b0] <= 32'd1;\n                    current_depth <= 8'd0;\n                    state <= SET_DEPTH;\n                end\n\n                SET_DEPTH: begin\n                    if (current_depth >= MAX_ITER) begin\n                        state <= DONE_ST;\n                    end else begin\n                        i <= 4'd0;\n                        j <= 4'd0;\n                        s <= 1'b0;\n                        state <= CHECK_STATE;\n                    end\n                end\n\n                CHECK_STATE: begin\n                    if (i > c50 || (i == c50 && j > c100)) begin\n                        current_depth <= current_depth + 8'd1;\n                        state <= SET_DEPTH;\n                    end else if (dist[i][j][s] == current_depth) begin\n                        // Setup for move generation\n                        if (s == 1'b0) begin\n                            max_x <= i;\n                            max_y <= j;\n                        end else begin\n                            max_x <= c50 - i;\n                            max_y <= c100 - j;\n                        end\n                        x <= 4'd0;\n                        y <= 4'd0;\n                        state <= CHECK_MOVE;\n                    end else begin\n                        state <= NEXT_STATE;\n                    end\n                end\n\n                NEXT_STATE: begin\n                    if (s == 1'b1) begin\n                        s <= 1'b0;\n                        if (j == c100) begin\n                            j <= 4'd0;\n                            i <= i + 4'd1;\n                        end else begin\n                            j <= j + 4'd1;\n                        end\n                    end else begin\n                        s <= s + 1'b1;\n                    end\n                    state <= CHECK_STATE;\n                end\n\n                CHECK_MOVE: begin\n                    if (x > max_x) begin\n                        state <= NEXT_STATE;\n                    end else if (y > max_y) begin\n                        y <= 4'd0;\n                        x <= x + 4'd1;\n                    end else begin\n                        if ((x + y > 4'd0) && ((x * 8'd50 + y * 8'd100) <= k)) begin\n                            // Calculate new state\n                            if (s == 1'b0) begin\n                                dist[i - x][j - y][1'b1] <= (dist[i][j][s] + 8'd1 < dist[i - x][j - y][1'b1]) ? \n                                                           dist[i][j][s] + 8'd1 : dist[i - x][j - y][1'b1];\n                                ways_arr[i - x][j - y][1'b1] <= (dist[i][j][s] + 8'd1 == dist[i - x][j - y][1'b1]) ? \n                                                            (ways_arr[i - x][j - y][1'b1] + (ways_arr[i][j][s] * C[i][x] * C[j][y])) % MOD : \n                                                            (dist[i][j][s] + 8'd1 < dist[i - x][j - y][1'b1]) ? \n                                                            (ways_arr[i][j][s] * C[i][x] * C[j][y]) % MOD : ways_arr[i - x][j - y][1'b1];\n                            end else begin\n                                dist[i + x][j + y][1'b0] <= (dist[i][j][s] + 8'd1 < dist[i + x][j + y][1'b0]) ? \n                                                           dist[i][j][s] + 8'd1 : dist[i + x][j + y][1'b0];\n                                ways_arr[i + x][j + y][1'b0] <= (dist[i][j][s] + 8'd1 == dist[i + x][j + y][1'b0]) ? \n                                                            (ways_arr[i + x][j + y][1'b0] + (ways_arr[i][j][s] * C[c50 - i][x] * C[c100 - j][y])) % MOD : \n                                                            (dist[i][j][s] + 8'd1 < dist[i + x][j + y][1'b0]) ? \n                                                            (ways_arr[i][j][s] * C[c50 - i][x] * C[c100 - j][y]) % MOD : ways_arr[i + x][j + y][1'b0];\n                            end\n                        end\n                        y <= y + 4'd1;\n                    end\n                end\n\n                DONE_ST: begin\n                    if (dist[4'd0][4'd0][1'b1] == INF) begin\n                        min_rides <= INF;\n                        ways <= 32'd0;\n                    end else begin\n                        min_rides <= dist[4'd0][4'd0][1'b1];\n                        ways <= ways_arr[4'd0][4'd0][1'b1] % MOD;\n                    end\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule